    /// Refuses a knob this command cannot honour. The flag the user
    /// typed is named, and the commands that do honour it are named too.
    public func requireHonoured(_ command: String) throws {
        guard let allowed = QWGKnobOptions.honoured[command] else { return }
        for id in explicitValues.keys.sorted() where !allowed.contains(id) {
            let flag = QWGKnobOptions.bindings.first { $0.id == id }?.flag ?? id
            let elsewhere = (QWGKnobOptions.honouredBy[id] ?? []).filter { $0 != command }
            throw QWGKnobNotHonoured(command: command, flag: flag, elsewhere: elsewhere)
        }
    }
