/// A knob the user set that the command cannot honour.
public struct QWGKnobNotHonoured: Error, CustomStringConvertible {
    /// The command that was asked.
    public let command: String
    /// The flag the user typed.
    public let flag: String
    /// The commands that do honour the knob.
    public let elsewhere: [String]

    public init(command: String, flag: String, elsewhere: [String]) {
        self.command = command
        self.flag = flag
        self.elsewhere = elsewhere
    }

    public var description: String {
        let hint = elsewhere.isEmpty
            ? ""
            : "; \(elsewhere.joined(separator: ", ")) honour\(elsewhere.count == 1 ? "s" : "") it"
        return "--\(flag) is not honoured by \(command)\(hint)"
    }
}
